with page (id) as ( select pm1_0.id from product pm1_0 where pm1_0.deleted_at is null order by pm1_0.price,pm1_0.id desc offset 4950 rows fetch first 50 rows only) select pm2_0.id,pm2_0.name,pm2_0.price,bm1_0.id,bm1_0.name,count(plm1_0.id) from page pg1_0 join product pm2_0 on pm2_0.id=pg1_0.id join brand bm1_0 on bm1_0.id=pm2_0.brand_id left join product_like plm1_0 on plm1_0.product_id=pm2_0.id group by pm2_0.id,bm1_0.id order by pm2_0.price,pm2_0.id desc
